Q: Can I iterate over/get an iterable over multiple promises by order of their settlement? A: <p>Here's a  function that maps input promises onto a new array of promises, each with its own  captured resolver.  As each input promise settles, it finds the first non-null resolver, calls it, and then nulls it.</p>
<p>To loop in settlement order, loop the new array, awaiting each. If you want a generator, move the caller's the loop into the function and yield each value. You can handle rejections by resolving to something like <code>{ status, value / reason }</code> instead of just the value.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function inSettlementOrder(promises) {
    const slots = [];
    const resolvers = [];

    for (let i = 0; i &lt; promises.length; i++) {
        slots[i] = new Promise(r =&gt; resolvers[i] = r);
    }

    for (const p of promises) {
        Promise.resolve(p).then(value =&gt; {
            const i = resolvers.findIndex(r =&gt; r !== null);
            resolvers[i](value);
            resolvers[i] = null;
        });
    }

    return slots;
}

async function test() {
    const promises = [
        new Promise(r =&gt; setTimeout(() =&gt; r("3 seconds"), 3000)),
        new Promise(r =&gt; setTimeout(() =&gt; r("1 second"), 1000)),
        new Promise(r =&gt; setTimeout(() =&gt; r("2 seconds"), 2000)),
    ];

    const slots = inSettlementOrder(promises);

    for (let i = 0; i &lt; slots.length; i++) {
        const value = await slots[i];
        console.log(value);
    }
}

test();</code></pre>
</div>
</div>
</p>
